INSERT INTO `spots` (`id`, `name_of_the_place`, `room_type`, `care_level`, `availability`, `available_from`, `available_spots`, `price_per_month`, `priority_score`, `plan_level_cached`, `latitude`, `longitude`, `address_street`, `postal_code`, `city`, `description`, `desc`, `user_id`, `status`, `is_featured`, `created_at`, `updated_at`) VALUES
(174,	'Jyoti Nursing Home',	'2',	'2',	'1',	NULL,	'12',	'5000',	'1',	'enterprise',	'26.9776592',	'75.7742494',	'Road No 4, Sikar Road, Vishwakarma Industrial Area',	'302013',	'Jaipur',	'Jyoti Nursing Home Pvt. Ltd. is an ISO 9001:2015 certified and NABH-accredited, 60-bed tertiary care facility. Over the decades, it has expanded from a small clinic to a comprehensive hospital employing between 200 and 500 medical and support staff. The hospital is directed by Dr. Avadh Bihari Maheshwari, with orthopedic surgeon Dr. J. P. Maheshwari and gynecologist Dr. Bindiya Bansal leading key departments.\r\njustdial.com+3',	'{\"en\":\"Jyoti Nursing Home Pvt. Ltd. is an ISO 9001:2015 certified and NABH-accredited, 60-bed tertiary care facility. Over the decades, it has expanded from a small clinic to a comprehensive hospital employing between 200 and 500 medical and support staff. The hospital is directed by Dr. Avadh Bihari Maheshwari, with orthopedic surgeon Dr. J. P. Maheshwari and gynecologist Dr. Bindiya Bansal leading key departments.\\r\\njustdial.com+3\",\"de\":\"tesf\"}',	56,	'active',	1,	'2026-01-03 08:05:39',	'2026-01-06 08:24:36'),
(175,	'Purvi Nursing Home & Diagnostic Centre',	'1',	'3',	'2',	NULL,	'12',	'10000',	'2',	'pro',	'26.8636772',	'75.7548060',	'48/110, Rajat Path, Kiran Path, Mansarovar Sector 6',	'302020',	'Jaipur',	'Purvi Nursing Home & Diagnostic Centre is a private multi-specialty healthcare facility located in the Mansarovar area of Jaipur, Rajasthan. It provides a combination of clinical and diagnostic services, catering to general medicine, pediatrics, pathology, and elder care. The center is known for personalized patient care and round-the-clock accessibility.',	'{\"en\":\"Purvi Nursing Home & Diagnostic Centre is a private multi-specialty healthcare facility located in the Mansarovar area of Jaipur, Rajasthan. It provides a combination of clinical and diagnostic services, catering to general medicine, pediatrics, pathology, and elder care. The center is known for personalized patient care and round-the-clock accessibility.\",\"de\":null}',	55,	'active',	0,	'2026-01-03 08:11:29',	'2026-01-06 05:47:58'),
(177,	'Care Nursing Home',	'1',	'1',	'2',	NULL,	'10',	'2000',	'4',	'free',	'26.8636772',	'75.7548060',	'249, Ghoda Nikas Rd, Tilak Nagar, Ramganj Bazar',	'302003',	'Jaipur',	'Care Nursing Home is a general hospital and diagnostic center located at 249, Ghoda Nikas Road, Tilak Nagar, Ramganj Bazar, Jaipur, Rajasthan 302003, India. It is recognized for providing accessible, round-the-clock healthcare services, especially in managing chronic conditions like diabetes, thyroid disorders, and blood pressure-related ailments.',	'{\"en\":\"Care Nursing Home is a general hospital and diagnostic center located at 249, Ghoda Nikas Road, Tilak Nagar, Ramganj Bazar, Jaipur, Rajasthan 302003, India. It is recognized for providing accessible, round-the-clock healthcare services, especially in managing chronic conditions like diabetes, thyroid disorders, and blood pressure-related ailments.\",\"de\":null}',	54,	'active',	0,	'2026-01-03 08:19:53',	'2026-01-06 05:47:47'),
(188,	'Rajasthan Nursing Home',	'2',	'4',	'3',	NULL,	NULL,	'15000',	'3',	'basic',	'22.345',	'22.14785',	'Gopalpura Bypass Rd, Krishna Vihar, Dayal Nagar, Gopal Pura Mode',	'302015',	'Jaipur',	NULL,	'{\"en\":\"Rajasthan Nursing Home is a multi-specialty healthcare facility in Jaipur, Rajasthan, India. Established in 1992, it operates as a 15-bed specialty hospital offering ethical, affordable, and high-quality medical care. The institution, also known as Rajasthan Nursing Home & Eye Centre, is recognized by the Rajasthan government and serves patients with modern diagnostic and surgical capabilities.\",\"de\":null}',	48,	'active',	0,	'2026-01-06 06:34:27',	'2026-01-06 06:34:27'),
(195,	'Nursing Care At Home pvt ltd',	'1',	'2',	'3',	NULL,	NULL,	'30000',	'2',	'pro',	'26.8053911',	'75.8032871',	'Goshala, Guru kripa complex, Near, Tonk Rd',	'302029',	'Jaipur',	NULL,	'{\"en\":null,\"de\":\"I will highly recommend their service . We received very knowledgeable and cooperative staff . Thanks for your support\"}',	55,	'active',	0,	'2026-01-15 08:03:54',	'2026-01-15 08:04:25'),
(196,	'Ashirvad old Age Home',	'1',	'4',	'1',	NULL,	NULL,	'50000',	'3',	'basic',	'26.8636772',	'75.8032871',	'34/458, near Haldighati Marg East, Sanganer, Sector 5, Pratap Nagar,',	'302033',	'Jaipur',	NULL,	'{\"en\":null,\"de\":\"Today, I had the opportunity to visit an old age home, and the experience truly touched my heart. Meeting the elderly residents reminded me of the value of compassion, patience, and simple human connection. Each person had a story to tell, and their smiles carried warmth and wisdom beyond words.\"}',	48,	'active',	0,	'2026-01-15 08:09:51',	'2026-01-15 08:10:02');
